      "kind": "internal",
      "type": "FLOAT32",
      "unit": "%",
      "access": "RW",
      "limits": {
        "min": 0,
        "max": 100
      },
      "initial": 85,
      "retain": true
    },
    {
      "id": "TANK01.VOLUME",
      "kind": "calculated",
      "type": "FLOAT32",
      "unit": "m3",
      "expression": "TANK01.LEVEL * 12.5"
    },
    {
      "id": "TANK01.HIGH",
      "kind": "calculated",
      "type": "BOOL",
      "expression": "TANK01.LEVEL > TANK01.SP_HI"
    },
    {
      "id": "PUMP01.STATE_TEXT",
      "kind": "calculated",
      "type": "STRING",
      "expression": "text(PUMP01.STATE, TrangThaiBom)"
    },
    {
      "id": "DEMO.WAVE",
      "kind": "simulation",
      "type": "FLOAT64",
      "sim": {
        "kind": "sine",
        "center": 50,
        "amplitude": 25,
        "periodMs": 20000
      }
    },
    {
      "id": "DEMO.SET",
      "kind": "simulation",
      "type": "INT16",
      "access": "RW",
      "limits": {
        "min": -100,
        "max": 100
      },
      "sim": {
        "kind": "manual",
        "initial": 0
      }
    },
    {
      "id": "K.MIN",
      "kind": "calculated",
      "type": "FLOAT64",
      "expression": "min(TANK01.LEVEL, TANK01.SP, 50)"
    },
    {
      "id": "K.MAX",
      "kind": "calculated",
      "type": "FLOAT64",
      "expression": "max(TANK01.LEVEL, 1)"
    },
    {
      "id": "K.ABS",
      "kind": "calculated",
      "type": "FLOAT64",
      "expression": "abs(TANK01.LEVEL - 50)"
    },
    {
      "id": "K.ROUND",
      "kind": "calculated",
      "type": "FLOAT64",
      "expression": "round(TANK01.LEVEL / 3, 2)"
    },
    {
      "id": "K.CLAMP",
      "kind": "calculated",
      "type": "FLOAT64",
      "expression": "clamp(TANK01.LEVEL - 5, 0, 100)"
    },
