    {
      "id": "PUMP01.STATE",
      "kind": "external",
      "type": "INT16",
      "valueTable": "TrangThaiBom",
      "source": {
        "device": "plc1",
        "address": "HR10"
      }
    },
    {
      "id": "METER1.P",
      "kind": "external",
      "type": "FLOAT32",
      "unit": "kW",
      "source": {
        "device": "meter1",
        "address": "30013"
      }
    },
    {
      "id": "PUMP01.FAULT",
      "kind": "external",
      "type": "BOOL",
      "source": {
        "device": "plc1",
        "address": "HR12.3"
      }
    },
    {
      "id": "PUMP01.NAME",
      "kind": "external",
      "type": "STRING",
      "source": {
        "device": "plc1",
        "address": "HR300",
        "stringLength": 16
      }
    },
    {
      "id": "TANK01.SP_HI",
      "kind": "internal",
      "type": "FLOAT32",
      "unit": "%",
      "access": "RW",
      "limits": {
        "min": 0,
        "max": 100
      },
      "initial": 85,
      "retain": true
    },
    {
      "id": "TANK01.VOLUME",
      "kind": "calculated",
      "type": "FLOAT32",
      "unit": "m3",
      "expression": "TANK01.LEVEL * 12.5"
