{
  "schemaVersion": "1.0.0",
  "id": "bom",
  "name": "Bơm có đèn và lưu lượng",
  "size": {
    "width": 220,
    "height": 140
  },
  "params": [
    {
      "name": "prefix",
      "kind": "tagPrefix",
      "default": "PUMP01"
    },
    {
      "name": "title",
      "kind": "string",
      "default": "Bơm"
    }
