      "id": "DEMO.WAVE",
      "kind": "simulation",
      "type": "FLOAT64",
      "sim": {
        "kind": "sine",
        "center": 50,
        "amplitude": 25,
        "periodMs": 20000
      }
    },
    {
      "id": "DEMO.SET",
      "kind": "simulation",
      "type": "INT16",
      "access": "RW",
      "limits": {
        "min": -100,
        "max": 100
      },
      "sim": {
        "kind": "manual",
        "initial": 0
      }
    },
    {
      "id": "PUMP02.CMD",
      "kind": "external",
      "type": "BOOL",
      "access": "RW",
      "source": {
        "device": "plc1",
        "address": "C11"
      }
    },
    {
