      "kind": "internal",
      "type": "STRING",
      "access": "RW",
      "limits": {
        "maxLength": 8
      },
      "initial": ""
    },
    {
      "id": "CNT.U16",
      "kind": "internal",
      "type": "UINT16",
      "access": "RW",
      "limits": {
        "min": 0,
        "max": 65535
      },
      "initial": 0
    },
    {
      "id": "SEL.TAB",
      "kind": "internal",
      "type": "INT16",
      "access": "RW",
      "limits": {
        "min": 0,
        "max": 5
      },
      "valueTable": "TrangThaiBom",
